namespace Commerce;

public sealed class ShoppingCart
{
    private readonly List<(string Sku, decimal Price, int Qty)> _items = new();
    private decimal _discountPercent;

    public void AddItem(string sku, decimal price, int qty) =>
        _items.Add((sku, price, qty));

    public bool RemoveItem(string sku) =>
        _items.RemoveAll(i => i.Sku == sku) > 0;

    public decimal GetTotal()
    {
        var subtotal = _items.Sum(i => i.Price * i.Qty);
        return subtotal - (subtotal * _discountPercent / 100m);
    }

    public bool ApplyPromoCode(string code) =>
        code switch
        {
            "SAVE10" => SetDiscount(10),
            "SAVE20" => SetDiscount(20),
            _ => false
        };

    private bool SetDiscount(decimal percent)
    {
        _discountPercent = percent;
        return true;
    }
}

