using Commerce;

namespace Commerce.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- AddItem Tests ---

    [TestMethod]
    public void AddItem_SingleItem_IncludedInTotal()
    {
        _cart.AddItem("SKU1", 10.00m, 2);

        Assert.AreEqual(20.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleItems_AllIncludedInTotal()
    {
        _cart.AddItem("SKU1", 5.00m, 1);
        _cart.AddItem("SKU2", 3.50m, 4);

        Assert.AreEqual(19.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSku_BothCounted()
    {
        _cart.AddItem("SKU1", 10.00m, 1);
        _cart.AddItem("SKU1", 10.00m, 1);

        Assert.AreEqual(20.00m, _cart.GetTotal());
    }

    // --- RemoveItem Tests ---

    [TestMethod]
    public void RemoveItem_ExistingItem_ReturnsTrue()
    {
        _cart.AddItem("SKU1", 10.00m, 1);

        Assert.IsTrue(_cart.RemoveItem("SKU1"));
    }

    [TestMethod]
    public void RemoveItem_ExistingItem_ExcludedFromTotal()
    {
        _cart.AddItem("SKU1", 10.00m, 1);
        _cart.AddItem("SKU2", 5.00m, 2);
        _cart.RemoveItem("SKU1");

        Assert.AreEqual(10.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentItem_ReturnsFalse()
    {
        Assert.IsFalse(_cart.RemoveItem("NOPE"));
    }

    [TestMethod]
    public void RemoveItem_DuplicateSku_RemovesAll()
    {
        _cart.AddItem("SKU1", 10.00m, 1);
        _cart.AddItem("SKU1", 7.00m, 2);
        _cart.RemoveItem("SKU1");

        Assert.AreEqual(0.00m, _cart.GetTotal());
    }

    // --- GetTotal Tests ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_ReflectsQuantity()
    {
        _cart.AddItem("SKU1", 2.50m, 3);

        Assert.AreEqual(7.50m, _cart.GetTotal());
    }

    // --- ApplyPromoCode Tests ---

    [TestMethod]
    public void ApplyPromoCode_ValidSave10_Applies10PercentDiscount()
    {
        _cart.AddItem("SKU1", 100.00m, 1);
        var result = _cart.ApplyPromoCode("SAVE10");

        Assert.IsTrue(result);
        Assert.AreEqual(90.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_ValidSave20_Applies20PercentDiscount()
    {
        _cart.AddItem("SKU1", 50.00m, 2);
        var result = _cart.ApplyPromoCode("SAVE20");

        Assert.IsTrue(result);
        Assert.AreEqual(80.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_ReturnsFalse()
    {
        _cart.AddItem("SKU1", 100.00m, 1);
        var result = _cart.ApplyPromoCode("BOGUS");

        Assert.IsFalse(result);
        Assert.AreEqual(100.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_SecondCodeOverridesFirst()
    {
        _cart.AddItem("SKU1", 100.00m, 1);
        _cart.ApplyPromoCode("SAVE10");
        _cart.ApplyPromoCode("SAVE20");

        Assert.AreEqual(80.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_EmptyCart_TotalRemainsZero()
    {
        _cart.ApplyPromoCode("SAVE10");

        Assert.AreEqual(0m, _cart.GetTotal());
    }
}

